CREATE FUNCTION public.kalzo_booking_step(p_booking uuid,p_action text,p_code text DEFAULT '',p_video text DEFAULT '') RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.bookings%ROWTYPE; c public.booking_codes%ROWTYPE; BEGIN SELECT * INTO b FROM public.bookings WHERE id=p_booking FOR UPDATE; IF NOT FOUND OR b.artist_owner_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Only the booked artist can perform this step'; END IF; IF b.status <> 'paid' THEN RAISE EXCEPTION 'Verified payment required'; END IF; SELECT * INTO c FROM public.booking_codes WHERE booking_id=p_booking FOR UPDATE; IF p_action='accept' AND b.workflow_stage='paid' THEN UPDATE public.bookings SET workflow_stage='accepted' WHERE id=p_booking; RETURN 'accepted'; ELSIF p_action='arrive' AND b.workflow_stage='accepted' THEN IF c.booking_id IS NULL OR c.expires_at<now() THEN RAISE EXCEPTION 'Arrival code is unavailable or expired'; END IF; UPDATE public.bookings SET workflow_stage='arrived' WHERE id=p_booking; RETURN 'arrived'; ELSIF p_action='arrival_code' AND b.workflow_stage='arrived' THEN IF c.arrival_used OR c.expires_at<now() OR c.arrival_attempts>=5 THEN RAISE EXCEPTION 'Arrival code unavailable, expired or locked'; END IF; IF c.arrival_code<>p_code THEN UPDATE public.booking_codes SET arrival_attempts=arrival_attempts+1 WHERE booking_id=p_booking; RETURN 'incorrect_code'; END IF; UPDATE public.booking_codes SET arrival_used=true WHERE booking_id=p_booking; UPDATE public.bookings SET workflow_stage='arrival_confirmed' WHERE id=p_booking; RETURN 'arrival_confirmed'; ELSIF p_action='venue_video' AND b.workflow_stage='arrival_confirmed' THEN IF p_video NOT LIKE auth.uid()::text||'/%' OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='kalzo-media' AND name=p_video) THEN RAISE EXCEPTION 'Upload your venue video first'; END IF; UPDATE public.bookings SET venue_video_path=p_video,workflow_stage='checked_in' WHERE id=p_booking; RETURN 'checked_in'; ELSIF p_action='start' AND b.workflow_stage='checked_in' THEN UPDATE public.bookings SET workflow_stage='performing' WHERE id=p_booking; RETURN 'performing'; ELSIF p_action='finish' AND b.workflow_stage='performing' THEN UPDATE public.bookings SET workflow_stage='finished' WHERE id=p_booking; RETURN 'finished'; ELSIF p_action='closing_code' AND b.workflow_stage='finished' THEN IF c.closing_used OR c.expires_at<now() OR c.closing_attempts>=5 THEN RAISE EXCEPTION 'Closing code unavailable, expired or locked'; END IF; IF c.closing_code<>p_code THEN UPDATE public.booking_codes SET closing_attempts=closing_attempts+1 WHERE booking_id=p_booking; RETURN 'incorrect_code'; END IF; UPDATE public.booking_codes SET closing_used=true WHERE booking_id=p_booking; UPDATE public.bookings SET workflow_stage='completed',payout_status='setup_required' WHERE id=p_booking; RETURN 'completed'; ELSIF p_action='decline' AND b.workflow_stage='paid' THEN UPDATE public.bookings SET workflow_stage='declined',refund_status='review_required' WHERE id=p_booking; RETURN 'declined'; END IF; RAISE EXCEPTION 'This action is not allowed at this booking stage'; END $$;
REVOKE ALL ON FUNCTION public.kalzo_booking_step(uuid,text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.kalzo_booking_step(uuid,text,text,text) TO authenticated;
CREATE FUNCTION public.kalzo_patron_codes(p_booking uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.bookings%ROWTYPE;c public.booking_codes%ROWTYPE; BEGIN SELECT * INTO b FROM public.bookings WHERE id=p_booking; IF NOT FOUND OR b.patron_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Codes are private to the booking patron'; END IF; SELECT * INTO c FROM public.booking_codes WHERE booking_id=p_booking; IF c.expires_at<now() THEN RETURN '{}'::jsonb; END IF; RETURN jsonb_build_object('arrival',CASE WHEN b.workflow_stage='arrived' AND NOT c.arrival_used THEN c.arrival_code ELSE NULL END,'closing',CASE WHEN b.workflow_stage='finished' AND NOT c.closing_used THEN c.closing_code ELSE NULL END); END $$;
REVOKE ALL ON FUNCTION public.kalzo_patron_codes(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.kalzo_patron_codes(uuid) TO authenticated;